package org.brightstats.data;
import com.google.gson.*;
import java.nio.file.*;
import java.util.*;
public final class DiagramChecks {
    static int checks;static void check(boolean value){checks++;if(!value)throw new AssertionError("Diagram check "+checks);}
    static void reject(Runnable action){try{action.run();throw new AssertionError("Invalid diagram operation accepted");}catch(IllegalArgumentException|ArithmeticException expected){checks++;}}
    public static void main(String[] args)throws Exception{JsonObject graph=JsonParser.parseString("{\"blocks\":[{\"name\":\"A α\",\"mode\":\"A\",\"columns\":[0],\"x\":140,\"y\":130},{\"name\":\"B\",\"mode\":\"B\",\"columns\":[1],\"x\":400,\"y\":130},{\"name\":\"C\",\"mode\":\"A\",\"columns\":[2],\"x\":660,\"y\":130}],\"edges\":[{\"source\":0,\"target\":1},{\"source\":1,\"target\":2},{\"source\":0,\"target\":2}]}").getAsJsonObject();DiagramClipboard.validate(graph,3);String copy=DiagramClipboard.copy(graph,new int[]{0,2},List.of("a","b","c"));var result=DiagramClipboard.paste(graph,copy,List.of("c","a","b"),35,45);var pasted=result.diagram();check(pasted.getAsJsonArray("blocks").size()==5);check(pasted.getAsJsonArray("edges").size()==4);check(Arrays.equals(result.added(),new int[]{3,4}));check(pasted.getAsJsonArray("blocks").get(3).getAsJsonObject().get("name").getAsString().equals("A α (copy 1)"));check(pasted.getAsJsonArray("blocks").get(3).getAsJsonObject().getAsJsonArray("columns").get(0).getAsInt()==1);check(pasted.getAsJsonArray("blocks").get(4).getAsJsonObject().getAsJsonArray("columns").get(0).getAsInt()==0);check(pasted.getAsJsonArray("blocks").get(3).getAsJsonObject().get("x").getAsDouble()==175);check(pasted.getAsJsonArray("edges").get(3).getAsJsonObject().get("source").getAsInt()==3);check(pasted.getAsJsonArray("edges").get(3).getAsJsonObject().get("target").getAsInt()==4);pasted.addProperty("modified",true);check(!result.diagram().has("modified"));check(graph.getAsJsonArray("blocks").size()==3);reject(()->DiagramClipboard.copy(graph,new int[]{0,0},List.of("a","b","c")));reject(()->DiagramClipboard.paste(graph,copy,List.of("a","b","missing"),0,0));JsonObject cycle=graph.deepCopy();cycle.getAsJsonArray("edges").add(JsonParser.parseString("{\"source\":2,\"target\":0}"));reject(()->DiagramClipboard.validate(cycle,3));JsonObject fractional=graph.deepCopy();fractional.getAsJsonArray("edges").get(0).getAsJsonObject().addProperty("source",.5);reject(()->DiagramClipboard.validate(fractional,3));JsonObject duplicates=graph.deepCopy();duplicates.getAsJsonArray("blocks").get(1).getAsJsonObject().addProperty("name","A α");reject(()->DiagramClipboard.validate(duplicates,3));reject(()->DiagramClipboard.paste(graph,"{\"format\":\"other\"}",List.of("a","b","c"),0,0));var history=new DiagramHistory(3,100000);history.reset(graph);check(!history.canUndo()&&!history.canRedo());history.record(result.diagram());check(history.canUndo()&&!history.canRedo());check(history.undo().equals(graph));check(history.canRedo());check(!history.record(graph));check(history.canRedo());check(history.redo().equals(result.diagram()));history.undo();JsonObject alternative=graph.deepCopy();alternative.getAsJsonArray("blocks").get(0).getAsJsonObject().addProperty("x",157);history.record(alternative);check(!history.canRedo());check(history.undo().equals(graph));JsonObject detached=history.current();detached.addProperty("modified",true);check(!history.current().has("modified"));for(int index=0;index<10;index++){JsonObject next=graph.deepCopy();next.addProperty("version",index);history.record(next);}check(history.retainedStates()==3);check(history.retainedBytes()<=100000);check(history.undo().get("version").getAsInt()==8);check(history.undo().get("version").getAsInt()==7);check(!history.canUndo());DiagramHistory small=new DiagramHistory(3,1024);small.reset(new JsonObject());JsonObject huge=new JsonObject();huge.addProperty("text","x".repeat(2048));reject(()->small.record(huge));check(small.retainedStates()==1&&!small.canUndo());Path output=Path.of(args[0]);Files.createDirectories(output);JsonObject evidence=new JsonObject();evidence.add("original",graph);evidence.add("payload",JsonParser.parseString(copy));evidence.add("pasted",result.diagram());evidence.addProperty("checks",checks);Files.writeString(output.resolve("checks.json"),new GsonBuilder().setPrettyPrinting().create().toJson(evidence));System.out.println("{\"checks\":"+checks+"}");}
}
